{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C16"],
      "claim": "Brigatinib, the highest-transfer analogue, has an absolute oral bioavailability of 46% in healthy volunteers, directly supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Delpazolid, a structurally related basic heteroaromatic amine, showed 99.75% absolute oral bioavailability in humans after 800 mg PO versus IV, strongly supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Tolvaptan, a moderately lipophilic amide analogue, had a mean absolute oral bioavailability of 56% (range 42-80%) in healthy subjects, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Sildenafil, a heteroaromatic basic amine drug, had an absolute oral bioavailability of 41% (90% CI 35.6-47.3) after 50 mg PO versus IV, supporting F >= 20% despite first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Rufloxacin, a fluoroquinolone with a basic amine, had at least 50% oral bioavailability in humans, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Prasugrel, a lipophilic ester-containing drug, had approximately 79% oral bioavailability in humans, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Amsacrine, an anilino acridine compound, had 32% oral bioavailability in patients, still above the 20% threshold and supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues show absolute oral bioavailability values from 32% to 99.75%, all above the 20% threshold. The query shares key features with these analogues—basic amine, heteroaromatic core, moderate lipophilicity—so the weight of evidence strongly supports high oral bioavailability.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement exists for the exact query molecule.",
    "First-pass metabolism and transporter-mediated efflux for the query are not directly characterized.",
    "The query's high ionization at physiological pH could reduce permeability, but analogues with similar basic centers still show high F."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

